import { visit } from 'unist-util-visit';
import { VISIBILITY_FOR_EXPECTED, isVisibilityElement, resolveVisibilityFor, } from './remarkVisibilityForMarkdown.js';
export const remarkValidateVisibility = () => (tree) => {
    visit(tree, (node) => {
        if (!isVisibilityElement(node))
            return;
        const resolution = resolveVisibilityFor(node);
        if (resolution.kind === 'invalid') {
            console.warn(`<Visibility for="${resolution.raw}"> has an unknown audience — expected ${VISIBILITY_FOR_EXPECTED}. The content will be hidden from humans.`);
        }
        if (resolution.kind === 'missing') {
            console.warn(`<Visibility> is missing its "for" audience — expected ${VISIBILITY_FOR_EXPECTED}. The content will be hidden from humans.`);
        }
    });
};
